import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define THREADS 256

__global__ void triplet_loss_kernel(const float4* __restrict__ anchor,
                                     const float4* __restrict__ positive,
                                     const float4* __restrict__ negative,
                                     float* __restrict__ loss_sum,
                                     int batch_size,
                                     int dim4,
                                     float margin) {
    int row = blockIdx.x;
    if (row >= batch_size) return;
    const float4* a = anchor + (size_t)row * dim4;
    const float4* p = positive + (size_t)row * dim4;
    const float4* n = negative + (size_t)row * dim4;
    float sum_pos = 0.0f;
    float sum_neg = 0.0f;
    for (int i = threadIdx.x; i < dim4; i += blockDim.x) {
        float4 av = a[i];
        float4 pv = p[i];
        float4 nv = n[i];
        float dpx = av.x - pv.x;
        float dpy = av.y - pv.y;
        float dpz = av.z - pv.z;
        float dpw = av.w - pv.w;
        float dnx = av.x - nv.x;
        float dny = av.y - nv.y;
        float dnz = av.z - nv.z;
        float dnw = av.w - nv.w;
        sum_pos += dpx * dpx + dpy * dpy + dpz * dpz + dpw * dpw;
        sum_neg += dnx * dnx + dny * dny + dnz * dnz + dnw * dnw;
    }
    __shared__ float shared_pos[THREADS];
    __shared__ float shared_neg[THREADS];
    int tid = threadIdx.x;
    shared_pos[tid] = sum_pos;
    shared_neg[tid] = sum_neg;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_pos[tid] += shared_pos[tid + s];
            shared_neg[tid] += shared_neg[tid + s];
        }
        __syncthreads();
    }
    if (tid == 0) {
        float d_pos = sqrtf(shared_pos[0]);
        float d_neg = sqrtf(shared_neg[0]);
        float l = d_pos - d_neg + margin;
        l = l > 0.0f ? l : 0.0f;
        atomicAdd(loss_sum, l);
    }
}
torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor,
                                        torch::Tensor positive,
                                        torch::Tensor negative,
                                        double margin) {
    TORCH_CHECK(anchor.is_cuda(), "anchor must be a CUDA tensor");
    TORCH_CHECK(positive.is_cuda(), "positive must be a CUDA tensor");
    TORCH_CHECK(negative.is_cuda(), "negative must be a CUDA tensor");
    anchor = anchor.contiguous();
    positive = positive.contiguous();
    negative = negative.contiguous();
    int batch_size = anchor.size(0);
    int dim = anchor.size(1);
    TORCH_CHECK(dim % 4 == 0, "dim must be divisible by 4 for vectorized kernel");
    int dim4 = dim / 4;
    auto loss_sum = torch::zeros({1}, anchor.options());
    dim3 grid(batch_size);
    dim3 block(THREADS);
    triplet_loss_kernel<<<grid, block>>>(
        reinterpret_cast<const float4*>(anchor.data_ptr<float>()),
        reinterpret_cast<const float4*>(positive.data_ptr<float>()),
        reinterpret_cast<const float4*>(negative.data_ptr<float>()),
        loss_sum.data_ptr<float>(),
        batch_size,
        dim4,
        (float)margin
    );
    auto loss = loss_sum / batch_size;
    return loss.squeeze();
}
'''

cpp_source = r'''
torch::Tensor triplet_margin_loss_cuda(torch::Tensor anchor,
                                        torch::Tensor positive,
                                        torch::Tensor negative,
                                        double margin);
'''

triplet_loss_module = load_inline(
    name='triplet_loss_module',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['triplet_margin_loss_cuda'],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    A model that computes Triplet Margin Loss for metric learning tasks
    using a custom fused CUDA kernel.

    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = margin

    def forward(self, anchor, positive, negative):
        return triplet_loss_module.triplet_margin_loss_cuda(anchor, positive, negative, self.margin)

